INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261114-0001', '2026-11-14', 'memini-author', 'foundation', 'Seed: first public snapshot (ADR-0002 decision 1). Built from the private repository at public-hygiene cf20c3e (on main 804fae9, which includes infra afb2b49) plus security-md 20ac9b1; features and bugs carry over as the baseline; private history, reviews and the merge checklist stay private', NULL, NULL, NULL, NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261114-0002', '2026-11-14', 'Claude/devops-498d4ec2', 'foundation', 'CI works on the public repo''s first commit and audits the right range: check_ledgers compares a true root commit against an empty ledger (shallow still fails, B-007) and takes --base; tools/ci/audit_range.py picks the base per event; ci.yml checks out the PR head; review gate on pull_request only until T-059 (temporary)', NULL, 'B-foundation-021', NULL, NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261114-0003', '2026-11-14', 'Claude/devops-498d4ec2', 'foundation', 'commit identity gate: author and committer emails must be on the public allow list tools/ci/commit-identities.txt (memini-author@example.invalid); pre-commit --pending and CI over the audit range; refused emails never printed; repo-local neutral identity set', NULL, NULL, NULL, NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261114-0004', '2026-11-14', 'Claude/devops-498d4ec2', 'foundation', 'export allow list: the neutral commit identity and the identity-gate test''s stand-in address are public on purpose', NULL, NULL, NULL, NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261114-0005', '2026-11-14', 'Claude/devops-498d4ec2', 'foundation', 'review of fix/ci-first-commit (devops-infra): audits fail closed on an empty, unknown or unrelated base (F1); no ref input on checkout (any ref makes it fetch from github.com, also under act); a separate step selects the PR head on pull requests (F2); identity gate checks author/committer names via tools/ci/commit-names.txt in hook and CI (F3)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261114-0006', '2026-11-14', 'Claude/devops-498d4ec2', 'foundation', 'test_wheel_install installs without --offline: offline resolution needs index metadata that uv sync --frozen never caches, so it failed on every clean machine (Tier 1, test setup was wrong; every test id survives)', NULL, NULL, NULL, NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0101', '2026-11-15', 'Claude/vprnd-8b35793b', 'foundation', 'module feature flags: memini.infra.flags with one env flag per unshipped engine module, OFF by default, read at call time (owner decision 2026-11-14; replaces the OpenFeature plan)', 'F-foundation-023', NULL, NULL, NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0105', '2026-11-15', 'Claude/vprnd-8b35793b', 'foundation', 'flags review fixes: MEMINI_ENABLE_DOCUMENT_AUTHORITY follows the MEMINI_ENABLE_<MODULE> pattern; a non-parametrized all-off test and a test that every public function is a listed flag are linked in the ledger; src/memini/infra/flags.py is a protected check file so a default can only be flipped with the owner''s approval', 'F-foundation-023', NULL, NULL, NULL, NULL);
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0106', '2026-11-15', 'shuraD', 'foundation', 'every new commit is the owner''s: the owner''s GitHub noreply address and login join the commit identity, name and export allow lists', NULL, NULL, NULL, NULL, 'owner 2026-11-15');
INSERT INTO change (id, date, author, module, summary, features, bugs, checks, review, approval) VALUES ('C-20261115-0001', '2026-11-15', 'Claude/orchestrator', 'orchestrator', 'Deterministic atomic-slice orchestrator (owner 2026-11-14, scope relayed by vp-rnd): python -m tools.orchestrator run/run-queue/check-spec/status/release; one-shot QA, coder and audit agents, path-based anti-cheat gate, sealed tests, host-side hold-out, ci.yml gates per env profile in fresh checkouts, one squash commit on main', 'F-orchestrator-001,F-orchestrator-002,F-orchestrator-003,F-orchestrator-004,F-orchestrator-005,F-orchestrator-006,F-orchestrator-007,F-orchestrator-008,F-orchestrator-009,F-orchestrator-010,F-orchestrator-011', NULL, 'pre-commit hook; pytest_gate full suite 1250 passed, coverage 92%; lint-imports, bandit, deptry, export gate', NULL, NULL);
